edits.before:
/* Keep long industrial-safety tables and inline equations inside the article. */
.industrial-safety-chapter article table{display:block;max-width:100%;overflow-x:auto;-webkit-overflow-scrolling:touch}
.industrial-safety-chapter article p .katex:not(:only-child),
.industrial-safety-chapter article li .katex{display:inline-block;max-width:100%;overflow-x:auto;overflow-y:hidden;vertical-align:middle;-webkit-overflow-scrolling:touch}
@media(min-width:768px){.industrial-safety-chapter article table{display:table}}

/* One-chapter preview: concentration conversion formula cards. */
article.formula-gray-sample .katex-display,
article.formula-gray-sample p>.katex:only-child{background:var(--gray-100);border-color:var(--gray-200);color:var(--gray-800)}

/* Bold only the math glyphs inside the one-chapter gray formula cards. */
article.formula-gray-sample .katex-display>.katex,
article.formula-gray-sample p>.katex:only-child{font-weight:var(--fw-bold)}

edits.after:
/* Keep long industrial-safety tables and inline equations inside the article. */
.industrial-safety-chapter article table{display:block;max-width:100%;overflow-x:auto;-webkit-overflow-scrolling:touch}
.industrial-safety-chapter article p .katex:not(:only-child),
.industrial-safety-chapter article li .katex{display:inline-block;max-width:100%;overflow-x:auto;overflow-y:hidden;vertical-align:middle;-webkit-overflow-scrolling:touch}
@media(min-width:768px){.industrial-safety-chapter article table{display:table}}

/* All chapter formula cards share the reviewed gray and bold treatment. */
.chapter-page article .katex-display,
.chapter-page article p>.katex:only-child{background:var(--gray-100);border-color:var(--gray-200);color:var(--gray-800)}
.chapter-page article .katex-display>.katex,
.chapter-page article p>.katex:only-child{font-weight:var(--fw-bold)}
.katex{font-size:1.06em}
